import{_ as r,C as s,c as l,o as m,a3 as o,j as e,G as a,a as n}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Equipment","description":"","frontmatter":{},"headers":[],"relativePath":"master/maintenance/equipments/equipments.md","filePath":"master/maintenance/equipments/equipments.md","lastUpdated":1791533670000}'),u={name:"master/maintenance/equipments/equipments.md"};function p(g,t,c,h,d,q){const i=s("ImagePopup");return m(),l("div",null,[t[7]||(t[7]=o('<h1 id="equipment" tabindex="-1">Equipment <a class="header-anchor" href="#equipment" aria-label="Permalink to &quot;Equipment&quot;">​</a></h1><p>In the <strong>Maintenance</strong> module, an <strong>Equipment</strong> is any physical asset your company owns and needs to keep in good working condition — for example a <em>Laptop</em>, <em>Printer</em>, <em>CNC Machine</em>, <em>Forklift</em>, or <em>Air Conditioner</em>. Each equipment record stores its identity (model, serial number), who owns it, who looks after it, when it was purchased, and how often it is expected to fail.</p><p><strong>Use Case:</strong> Create an equipment record for every machine, tool, vehicle, or device you want to track. Once an equipment exists in the system, you can raise <a href="./../operations/maintenance-requests.html">Maintenance Requests</a> against it, assign a technician, and monitor how often it breaks down.</p><blockquote><p><strong>In simple words:</strong> Equipment is the <em>thing you take care of</em>. Before you can log a repair or schedule a check-up, the item must exist here.</p></blockquote><h2 id="steps-to-create-a-new-equipment" tabindex="-1">Steps to Create a New Equipment <a class="header-anchor" href="#steps-to-create-a-new-equipment" aria-label="Permalink to &quot;Steps to Create a New Equipment&quot;">​</a></h2>',5)),e("ol",null,[e("li",null,[t[0]||(t[0]=e("p",null,[n("Navigate to "),e("strong",null,[e("code",null,"Maintenance → Equipment")]),n(" as shown below:")],-1)),a(i,{src:"/images1/maintenance/equipment_navigation.png",alt:"Equipment Navigation"})]),e("li",null,[t[1]||(t[1]=o('<p>Fill in the following details:</p><h4 id="general-information" tabindex="-1">General Information <a class="header-anchor" href="#general-information" aria-label="Permalink to &quot;General Information&quot;">​</a></h4><ul><li><strong><em>Name:</em></strong> The name of the equipment (e.g. <code>Laptop - Dell Latitude 5420</code>). This is shown everywhere the equipment is referenced.</li><li><strong><em>Description:</em></strong> A free-text note describing the equipment, its purpose, or any extra information that helps identify it.</li></ul>',3)),a(i,{src:"/images1/maintenance/equipment_general_section.png",alt:"Equipment General Section"}),t[2]||(t[2]=o('<h4 id="product-information" tabindex="-1">Product Information <a class="header-anchor" href="#product-information" aria-label="Permalink to &quot;Product Information&quot;">​</a></h4><ul><li><strong><em>Vendor:</em></strong> The supplier or vendor from whom the equipment was purchased.</li><li><strong><em>Vendor Reference:</em></strong> The reference number or code given by the vendor (e.g. invoice number, vendor SKU).</li><li><strong><em>Model:</em></strong> Model name or number of the equipment (e.g. <code>Latitude 5420</code>).</li><li><strong><em>Serial Number:</em></strong> Unique serial number printed on the equipment — useful for warranty claims and traceability.</li><li><strong><em>Effective Date:</em></strong> The date the equipment was put into use. This is the starting point the system uses to calculate the <strong>Mean Time Between Failures (MTBF)</strong>.</li><li><strong><em>Cost:</em></strong> The purchase or acquisition cost of the equipment.</li><li><strong><em>Warranty Expiration Date:</em></strong> The date when the vendor warranty ends. Useful for planning replacements or claiming repairs under warranty.</li></ul>',2)),a(i,{src:"/images1/maintenance/equipment_product_information.png",alt:"Equipment Product Information"}),t[3]||(t[3]=o('<h4 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h4><ul><li><strong><em>Equipment Category:</em></strong> Choose a <a href="./../configurations/categories.html">Category</a> (e.g. <em>Computers</em>, <em>Vehicles</em>, <em>Tools</em>) to group similar equipment together. Selecting a category auto-fills the default technician for that category.</li><li><strong><em>Maintenance Team:</em></strong> The <a href="./../configurations/teams.html">Team</a> responsible for taking care of this equipment.</li><li><strong><em>Company:</em></strong> The company that owns this equipment (useful in multi-company setups).</li><li><strong><em>Technician:</em></strong> The person primarily responsible for maintaining this equipment. Defaults to the technician set on the chosen category.</li><li><strong><em>Owner:</em></strong> The user who owns or uses this equipment day-to-day (e.g. the employee a laptop is assigned to).</li><li><strong><em>Used in Location:</em></strong> Free-text field describing where the equipment is physically located (e.g. <em>Floor 2, Cabin 12</em>, <em>Warehouse A</em>).</li></ul>',2)),a(i,{src:"/images1/maintenance/equipment_settings_section.png",alt:"Equipment Settings Section"}),t[4]||(t[4]=e("h4",{id:"maintenance",tabindex:"-1"},[n("Maintenance "),e("a",{class:"header-anchor",href:"#maintenance","aria-label":'Permalink to "Maintenance"'},"​")],-1)),t[5]||(t[5]=e("ul",null,[e("li",null,[e("strong",null,[e("em",null,"Expected Mean Time Between Failure:")]),n(" The number of days you expect the equipment to run between two breakdowns. Helps you plan preventive maintenance before the next failure is due.")])],-1)),a(i,{src:"/images1/maintenance/equipment_maintenance_section.png",alt:"Equipment Maintenance Section"})]),t[6]||(t[6]=e("li",null,[e("p",null,[e("strong",null,"Action Buttons:")]),e("ul",null,[e("li",null,[e("strong",null,"Create"),n(" – Save and open the equipment record.")]),e("li",null,[e("strong",null,"Create & Create Another"),n(" – Save and immediately open another blank form.")]),e("li",null,[e("strong",null,"Cancel"),n(" – Discard the entry and return to the list view.")])])],-1))]),t[8]||(t[8]=e("h2",{id:"equipment-view-page",tabindex:"-1"},[n("Equipment View Page "),e("a",{class:"header-anchor",href:"#equipment-view-page","aria-label":'Permalink to "Equipment View Page"'},"​")],-1)),t[9]||(t[9]=e("p",null,[n("After creation, you are redirected to the "),e("strong",null,"Equipment View Page"),n(", where you can review every detail.")],-1)),a(i,{src:"/images1/maintenance/equipment_view_page.png",alt:"Equipment View Page"}),t[10]||(t[10]=o('<p>On this page you can see:</p><ul><li><strong>General Information</strong> — name and description.</li><li><strong>Product Information</strong> — vendor, model, serial number, cost, dates.</li><li><strong>Settings</strong> — category, team, technician, owner, location.</li><li><strong>Maintenance</strong> — expected MTBF, total maintenance count, currently open maintenance count, assigned date, and scrap date.</li></ul><p>You can also:</p><ul><li><strong>Edit:</strong> Modify any saved field.</li><li><strong>Delete / Archive:</strong> Remove or archive the equipment. Archived equipment stays in the database but no longer appears in selection lists.</li></ul><h2 id="list-view-—-filters-groups-actions" tabindex="-1">List View — Filters, Groups &amp; Actions <a class="header-anchor" href="#list-view-—-filters-groups-actions" aria-label="Permalink to &quot;List View — Filters, Groups &amp; Actions&quot;">​</a></h2><p>The <strong>Equipment</strong> list view shows every equipment record with the following columns: <strong>Equipment Name</strong>, <strong>Owner</strong>, <strong>Serial Number</strong>, <strong>Technician</strong>, <strong>Equipment Category</strong>, and <strong>Company</strong>.</p><p>You can:</p><ul><li><strong>Filter by:</strong> Equipment Category, Maintenance Team, or Technician.</li><li><strong>Group by:</strong> Technician, Equipment Category, Owner, or Vendor.</li><li><strong>Search by:</strong> Name or Serial Number.</li><li><strong>Bulk Actions:</strong> Archive, restore, or permanently delete selected equipment.</li></ul>',8)),a(i,{src:"/images1/maintenance/equipment_list_view.png",alt:"Equipment List View"}),t[11]||(t[11]=o('<h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>The <strong>Equipment</strong> section is the foundation of the Maintenance module. By keeping every asset listed here with the right category, team, and technician, you can:</p><ul><li>Raise <a href="./../operations/maintenance-requests.html">Maintenance Requests</a> for any breakdown or check-up.</li><li>Track how many times each equipment has been repaired.</li><li>Plan <strong>preventive maintenance</strong> using the expected MTBF.</li><li>Get warranty alerts before the warranty expires.</li></ul><blockquote><p><strong>Next step:</strong> Once your equipment is added, set up the supporting <a href="./../configurations/categories.html">Categories</a>, <a href="./../configurations/teams.html">Teams</a>, and <a href="./../configurations/stages.html">Stages</a>, and then start logging <a href="./../operations/maintenance-requests.html">Maintenance Requests</a>.</p></blockquote>',4))])}const y=r(u,[["render",p]]);export{_ as __pageData,y as default};
